import{createFrog,stroke,release,advance,cancelControls,RHYTHM,obstacleAt,nudge}from'./core.mjs';
const $=id=>document.getElementById(id),canvas=$('pond'),ctx=canvas.getContext('2d'),buttons=[...document.querySelectorAll('[data-limb]')],keys={a:0,d:1,j:2,k:3},names=['LEFT HAND','RIGHT HAND','LEFT FOOT','RIGHT FOOT'];let s=createFrog(),best=+(localStorage.getItem('swim-off-best-v1')||0),last=performance.now(),camera=0,clock=0,hit=new Set();$('best').textContent=`${Math.floor(best)} m`;
function begin(){s=createFrog();s.status='playing';camera=clock=0;hit.clear();last=performance.now();$('overlay').hidden=true;$('share').hidden=true;sync()}
function finish(){best=Math.max(best,s.z);localStorage.setItem('swim-off-best-v1',best);$('best').textContent=`${Math.floor(best)} m`;$('overlay-label').textContent='CERTIFIED RIVER GOBLIN';$('overlay-title').textContent=`${Math.floor(s.z)} meters. Splash.`;$('overlay-copy').textContent=`${s.strokes} clean strokes. ${s.strokes<4?'Follow the glowing limb to start the swim cycle.':'You found the rhythm. Now go farther.'}`;$('start').textContent='SWIM AGAIN →';$('share').hidden=false;$('overlay').hidden=false;sync()}
function pause(){if(s.status!=='playing')return;s.status='paused';cancelControls(s);$('overlay-label').textContent='FLOAT BREAK';$('overlay-title').textContent='Just drifting.';$('overlay-copy').textContent='The frog is conserving highly valuable energy.';$('start').textContent='KEEP SWIMMING →';$('share').hidden=true;$('overlay').hidden=false;sync()}
$('start').onclick=()=>s.status==='paused'?(s.status='playing',last=performance.now(),$('overlay').hidden=true):begin();$('restart').onclick=begin;$('pause').onclick=pause;$('help').onclick=()=>{pause();$('help-dialog').showModal()};$('close-help').onclick=$('got-it').onclick=()=>$('help-dialog').close();
function press(i){if(stroke(s,i,clock)){nudge(s,i%2? .045:-.045)}sync()}function lift(i){release(s,i);sync()}buttons.forEach((b,i)=>{b.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();b.setPointerCapture(e.pointerId);press(i)};b.onpointerup=b.onpointercancel=()=>lift(i)});const held=new Set();addEventListener('keydown',e=>{if(e.key==='Escape')return pause();const k=e.key.toLowerCase();if(!(k in keys)||e.repeat||held.has(k))return;e.preventDefault();held.add(k);press(keys[k])});addEventListener('keyup',e=>{const k=e.key.toLowerCase();if(k in keys){held.delete(k);lift(keys[k])}});addEventListener('blur',pause);document.addEventListener('visibilitychange',()=>document.hidden&&pause());
function sync(){buttons.forEach((b,i)=>{b.classList.toggle('active',s.active[i]);b.classList.toggle('next',i===RHYTHM[s.next]);b.setAttribute('aria-pressed',String(s.active[i]))});$('rhythm-label').textContent=`NEXT: ${names[RHYTHM[s.next]]} · COMBO x${s.combo}`;$('feedback').textContent=s.message;$('energy').value=s.stamina;$('speed').value=s.speed;$('distance').innerHTML=`${Math.floor(s.z)}<span>m</span>`;$('strokes').textContent=`${s.strokes} clean ${s.strokes===1?'stroke':'strokes'}`}
function ellipse(x,y,rx,ry,fill){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,7);ctx.fillStyle=fill;ctx.fill()}function line(a,b,color,w){ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.strokeStyle=color;ctx.lineWidth=w;ctx.lineCap='round';ctx.stroke()}
function frog(x,y,scale){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);const kick=Math.sin(clock*11)*4;ellipse(0,7,31,38,'#91d859');ellipse(0,-17,35,27,'#b7ed70');for(const side of[-1,1]){line([side*23,6],[side*(48+kick),25],'#164c45',13);line([side*23,6],[side*(48+kick),25],side<0?'#bda2ff':'#ff9aca',8);line([side*18,28],[side*(36-kick),49],'#164c45',14);line([side*18,28],[side*(36-kick),49],side<0?'#d5ff6f':'#7aecd9',9);ellipse(side*22,-36,14,18,'#b7ed70');ellipse(side*22,-40,8,10,'#fff');ellipse(side*22,-42,4,5,'#173e3d')}ctx.restore()}
function draw(dt){const w=canvas.clientWidth,h=canvas.clientHeight,d=Math.min(devicePixelRatio||1,2);if(canvas.width!==w*d||canvas.height!==h*d){canvas.width=w*d;canvas.height=h*d}ctx.setTransform(d,0,0,d,0,0);const bg=ctx.createLinearGradient(0,0,0,h);bg.addColorStop(0,'#163453');bg.addColorStop(1,'#19a5a0');ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);camera+=(s.z-camera)*(1-Math.exp(-5*dt));for(let i=0;i<18;i++){const z=Math.floor(camera/5)*5+i*5-camera,x=w/2+Math.sin((camera+z)*.05)*w*.08,y=h-z*17;ctx.strokeStyle='#8fffff18';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,y);ctx.quadraticCurveTo(x,y+8,w,y);ctx.stroke()}for(let i=Math.max(0,Math.floor(camera/13)-1);i<Math.floor(camera/13)+7;i++){const o=obstacleAt(i),dy=o.z-camera;if(dy<0||dy>34)continue;const y=h*.76-dy*h*.022,x=w/2+o.x*w*.34,scale=1-dy*.014;if(o.kind==='log'){ctx.fillStyle='#704b36';ctx.fillRect(x-34*scale,y-7,68*scale,14)}else if(o.kind==='lily'){ellipse(x,y,28*scale,11*scale,'#75c95f')}else{ctx.save();ctx.translate(x,y);ctx.rotate(.4);ctx.fillStyle='#f493cf';ctx.fillRect(-7,-18,14,36);ctx.restore()}}const fx=w/2+s.x*w*.29,fy=h*.76;if(s.status==='playing')for(let i=Math.max(0,Math.floor(camera/13)-1);i<Math.floor(camera/13)+2;i++){const o=obstacleAt(i);if(hit.has(i)||Math.abs(o.z-s.z)>1.1||Math.abs(o.x-s.x)>.28)continue;hit.add(i);s.speed*=.45;s.stamina=Math.max(0,s.stamina-12);s.combo=0;s.message='BONK. Keep swimming—rhythm fixes everything.'}ellipse(fx,fy+35,38,10,'#073f6088');frog(fx,fy,.72);ctx.fillStyle='#d5ff6f';ctx.font='bold 10px Arial';ctx.textAlign='center';ctx.fillText(`${Math.round(s.speed*10)/10} m/s`,fx,fy-55)}
function frame(now){const dt=Math.min(.04,(now-last)/1000);last=now;clock+=dt;const before=s.status;advance(s,dt);if(before==='playing'&&s.status==='over')finish();sync();draw(dt);requestAnimationFrame(frame)}$('share').onclick=async()=>{const text=`My frog swam ${Math.floor(s.z)}m using four extremely coordinated limbs. Beat that. 🐸`,url=new URL('/frog/',location.href).href;try{if(navigator.share)await navigator.share({title:'SWIM OFF!',text,url});else await navigator.clipboard.writeText(`${text} ${url}`)}catch{}};sync();requestAnimationFrame(frame);
